package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaZhDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_sami" to DuaText("远离我感官的邪恶", "安拉啊，我向你寻求庇护，使我免受听觉的邪恶、视觉的邪恶、舌头的邪恶、内心的邪恶和欲望的邪恶。", "受教于 Shakal ibn Humayd (RA)。", "保护四肢和自我免受罪恶侵害的二重奏。"),
        "dua_hadm_gharaq" to DuaText("避免突然死亡和意外事故", "安拉啊，我向你寻求庇护，免遭（被建筑物压碎）、从高处坠落、溺水、燃烧和衰老；来自恶魔在死亡时引导我误入歧途，来自于逃离你的道路而死亡，以及死于（毒）螫刺。", "避免事故和惨死。", "躲避先知 ﷺ 的双重庇护。"),
        "dua_ju_khiyanah" to DuaText("逃离饥饿和背叛", "安拉啊，我向你寻求庇护，免遭饥饿，因为它是邪恶的同伴；我向你寻求庇护，免遭背叛，因为它是邪恶的知己。", "躲避饥饿和背叛。", "躲避先知 ﷺ 的双重庇护。"),
        "dua_huda_tuqa" to DuaText("指导、虔诚、贞洁和充足", "安拉啊，我祈求您的指导、虔诚、贞洁和自给自足。", "先知 ﷺ 的简短而全面的二重奏。", "宗教和这个世界的四个基本祝福。"),
        "dua_aslih_li_dini" to DuaText("纠正我的宗教、世界和来世", "安拉啊，请纠正我的宗教信仰，这是我一切事务的保障；纠正我的世俗生活，这是我的生计；并纠正我的后世，我将回到那里。使生命使我在一切善事上增长，使死亡使我摆脱一切邪恶。", "改革宗教、今世和后世——这三者。", "先知 ﷺ 的综合二重唱。"),
        "dua_musarrifal_qulub" to DuaText("让我们的心顺服你", "安拉啊，心灵的转动者，请将我们的心转向你的服从。", "使心坚定服从的二重奏。", "所有人的心都在至仁主的两根手指之间。"),
        "dua_jannah_nar" to DuaText("寻求詹纳（Jannah），避难所", "安拉啊，我祈求您赐予我天堂，并寻求您的庇护，使我免于火狱。", "在 tashahhud 之后或任何时间。", "先知 ﷺ 说：我们的杜阿也围绕这个。"),
        "dua_khayri_kullih" to DuaText("一切都好，现在和以后", "安拉啊，我向你祈求所有的好处——即时的和延迟的，我知道的和我不知道的——我向你寻求庇护，免受所有邪恶的伤害——即时的和延迟的，我知道的和我不知道的。安拉啊，我祈求你赐予天堂和一切使我接近天堂的言语和行为，我寻求你的庇护，免受火和任何使我接近天堂的言语和行为。", "先知 ﷺ 向艾莎 (RA) 教授了这个全面的杜阿（杜阿的一部分）。", "集一切美好于一身的二人组。"),
        "dua_ihdini_saddidni" to DuaText("引导我并让我保持正直", "安拉啊，请引导我并让我走在正确的道路上。", "先知 ﷺ 将其传授给阿里 (RA)。", "将引导视为沿着道路被引导，将萨达视为箭的笔直。"),
        "dua_hubbaka" to DuaText("祈求安拉的爱", "安拉啊，我祈求你的爱，那些爱你的人的爱，以及让我得到你的爱的行为。安拉啊，让你的爱对我来说比我自己、我的家人和冷水更珍贵。", "先知 ﷺ 记载了达乌德 (AS) 的杜阿。", "安拉的爱是最大的财富。"),
        "dua_filal_khayrat" to DuaText("行善离恶", "安拉啊，我祈求您使我能够行善，戒除恶行，爱护穷人，并宽恕我并怜悯我。当你打算对一个民族进行审判时，请在不经受审判的情况下接受我。我祈求你的爱，那些爱你的人的爱，以及让我接近你的爱的行为的爱。", "安拉在梦中向先知 ﷺ 教导了这个 dua。", "先知 ﷺ 说：这是真的，所以学习它并教导它。"),
        "dua_bi_ilmikal_ghayb" to DuaText("让我活得美好", "安拉啊，通过你对看不见的知识和你对创造的力量——只要你知道生命对我更好，就让我活下去；当你知道死亡对我更好时，请带走我。安拉啊，我祈求您在私下和公开场合敬畏您，在满足和愤怒时祈求真理之言，在贫穷和财富中祈求节制。", "阿马尔·伊本·亚西尔 (Ammar ibn Yasir) 的祈祷二重奏 (RA)（开头部分）。", "先知 ﷺ 在祈祷中做了这个杜阿。"),
        "dua_ism_azam_mannan" to DuaText("Ism-e-Azam：阿尔-曼南", "安拉啊，我祈求你，一切赞美都归于你；除您之外，别无神明，您是恩惠的赐予者，天地的创造者。哦，威严和荣誉的拥有者，哦，永生者，哦，维持者！", "先知 ﷺ 说这个人以真主至大的名字创造了杜阿。", "用这个名字做的二重奏得到了回答。"),
        "dua_ism_azam_ahad_samad" to DuaText("Ism-e-Azam：阿哈德·阿斯·萨马德", "安拉啊，我祈求你，因为我见证你是安拉；除了祢之外，没有任何神，祢是独一者，自足者，既不生育也不出生，没有任何神可以与他相比。", "先知 ﷺ 说这个人以他至大的名字求问安拉。", "当它要求时，他给予；当它要求时，他给予；当它呼唤时，他就会回应。"),
        "dua_thabbitni_hadiyan" to DuaText("让我坚定、有引导、有引导", "安拉啊，请让我坚定，让我成为一个引导者和被引导者。", "先知 ﷺ 为贾里尔 (RA) 做了这个杜阿（为你自己说“thabbitni”）。", "Jarir (RA) 的原始 dua 使用单词“thabbit-hu”。"),
        "dua_rabbighfir_tub_alayya" to DuaText("原谅我并接受我的悔改", "主啊，请原谅我并接受我的悔改。事实上，您是悔改的接受者，是仁慈的。", "一次静坐一百次——先知 ﷺ 的实践。", "圣门弟子们统计，先知 ﷺ 一口气说了一百遍。"),
        "dua_rafiq_ala" to DuaText("临终之人的杜阿", "安拉啊，宽恕我，怜悯我，让我与至高伴侣在一起。", "先知 ﷺ 的最后一句——让病人为自己说。", "先知 ﷺ 在他去世时做了这个杜阿。"),
        "dua_la_bas_tahur" to DuaText("安慰病人：净化", "没有伤害；如果安拉愿意的话，这是（从罪恶中）的净化。", "探访时安慰病人。", "先知 ﷺ 在探望病人时这样说。"),
        "dua_talqeen" to DuaText("塔尔金为垂死之人", "除安拉外，没有人有权受到崇拜。", "在临终者身边背诵卡利玛（不要强迫他们说）。", "谁的遗言是“La ilaha illallah”，谁就将进入天堂（Abu Dawud 3116）。"),
        "dua_ahyini_ma_kanat" to DuaText("而不是希望死亡", "安拉啊，只要生命对我来说更好，请让我活下去，当死亡对我更好时，请带走我。", "而不是希望在苦难中死去。", "先知 ﷺ 禁止祈求死亡，并教导了这一点。"),
        "dua_for_one_i_cursed" to DuaText("对于我用言语伤害的人", "安拉啊，任何被我侮辱的信徒，请让这成为他在复活日接近你的一种方式。", "对于你在愤怒中说坏话的人。", "先知 ﷺ 的二重唱。"),
        "dua_praising_someone" to DuaText("赞美某人时", "我认为某人就是这样，真主是他的清算者，我不保证任何人在真主面前是纯洁的。", "赞美某人时，不要夸大其词。", "先知 ﷺ 教导了这种赞美的礼仪。"),
        "dua_being_praised" to DuaText("当你被表扬时", "安拉啊，不要因为他们所说的话而对我负责，也不要因为他们不知道的事情而原谅我。", "听到自己受到赞扬时——同伴的做法(RA)。", "这是一种在受到表扬时避免傲慢的方法。"),
        "dua_non_muslim_sneezes" to DuaText("当非穆斯林打喷嚏时", "愿真主引导你并纠正你的事务。", "当非穆斯林打喷嚏并说“Alhamdulillah”时。", "犹太人会在先知 ﷺ 附近打喷嚏，希望他说“Yarhamukallah”，他就会这么说。"),
        "dua_reply_ahl_kitab_salam" to DuaText("回复《圣书之人》萨拉姆", "还有你。", "当圣书之民以萨拉姆问候时。", "先知 ﷺ 的指示。"),
        "dua_fasting_invited" to DuaText("禁食期间受邀时", "我正在禁食。", "当禁食期间受到邀请时，或者当有人与你争吵时。", "如果封斋者接受邀请，他应该为主人祈祷。"),
        "dua_for_who_gave_drink" to DuaText("献给谁养活了我", "安拉啊，请喂给我食物的人，请给给我饮料的人饮料。", "对于给你食物或饮料的人。", "先知 ﷺ 为 al-Miqdad (RA) 做了这个杜阿。"),
        "dua_eid_greeting" to DuaText("开斋节问候", "愿真主接受我们和你们的（善行）。", "在开斋节那天互相交流——高贵的同伴 (RA) 的做法。", "同伴们在开斋节聚会时这么说。"),
        "dua_wedding_night" to DuaText("为尼卡之后的新娘", "安拉啊，我祈求你赐予她善良和你创造她的本性的善良，我向你寻求庇护，免受她的邪恶和你创造她的本性的邪恶。", "尼卡之后，将手放在妻子的额头上。", "先知 ﷺ 的教导——婚姻的祝福。"),
        "dua_istisqa_ibadak" to DuaText("给你的仆人和动物浇水", "安拉啊，请赐水给你的仆人和动物，传播你的仁慈，赐予你死去的土地以生命。", "求雨（istisqa）。", "先知 ﷺ 创造了这个杜阿来祈雨。"),
        "dua_seeing_clouds" to DuaText("看到乌云密布", "安拉啊，我向你寻求庇护，免受邪恶之害。", "当看到天空中乌云时；如果下雨，请说“Allahumma sayyiban nafi'a”。", "当看到云彩时，先知 ﷺ 就会离开他正在做的事情并进行这个杜阿。"),
        "dua_jamarat" to DuaText("用石头砸死贾马拉特", "安拉是最伟大的。", "每扔一块石子。", "先知 ﷺ 对每一块卵石都念诵了 takbir，然后在第一次和第二次 Jamrah 面向 Qiblah 并做了一个长的 dua。"),
        "dua_rabbi_ainni" to DuaText("我的主啊，请帮助我，而不是反对我", "我的主啊，帮助我而不帮助别人反对我，赐我胜利而不让别人战胜我，为我谋划而不为我谋害，引导我并且使引导容易为我所用，帮助我反对那些冤枉我的人。", "先知 ﷺ 的综合二重奏（开场部分）。", "一个聚集了宗教和这个世界的一切帮助的二人组。"),
        "dua_ati_nafsi_taqwaha" to DuaText("授予我的灵魂 Taqwa", "安拉啊，请赐予我的灵魂虔诚并净化它，因为你是净化它的最佳人选。你是它的守护者和主人。", "为了改造和净化自我。", "先知 ﷺ 曾经制作过这个 dua。"),
        "dua_iqsim_lana_khashyatik" to DuaText("让我们对你如此恐惧", "安拉啊，请赐予我们足够的敬畏你的力量，使我们能够不服从你；赐予我们足够的服从，使我们进入你的天堂；赐予我们足够的确定性，使我们能够轻松应对这个世界的灾难。只要你让我们活着，让我们享受我们的听觉、视觉和力量，并让它们比我们更长寿。向那些伤害我们的人报仇，帮助我们对抗敌人，不要让我们的灾难成为我们的宗教，不要让这个世界成为我们最大的关注或我们知识的限制，不要让那些不怜悯我们的人凌驾于我们之上。", "当从聚会中起身时，先知 ﷺ 很少会不做这句杜阿而起身。", "为了宗教、今世和后世的利益而进行的全面的二重奏。"),
        "dua_infani_bima_allamtani" to DuaText("你教给我的东西让我受益匪浅", "安拉啊，请用你所教给我的东西来使我受益，教给我对我有益的东西，并增加我的知识。", "在寻求知识时或学习之前。", "有益的知识和据此采取行动的二重奏。"),
        "dua_jar_su" to DuaText("躲避坏邻居", "安拉啊，我在永久居住地向你寻求庇护，免受坏邻居的伤害，因为旅途中的邻居继续前进。", "为了免受坏邻居的侵害。", "先知 ﷺ 命人寻求庇护。"),
        "dua_ishfi_abdak" to DuaText("为了病人的康复", "安拉啊，请治愈你的仆人，以便他可以为你对抗敌人，或者为你行走祈祷。", "为病人探望时。", "先知 ﷺ 教导对病人说这句话。"),
        "dua_la_mania" to DuaText("无人能拒绝你所给予的", "除了真主之外，没有人有权利被崇拜，独自一人，没有伴侣。统治权归他所有，赞美归他所有，他对万事都有能力。安拉啊，没有人能扣留你所给予的，也没有人能给予你所扣留的，富人的财富对你来说毫无用处。", "在义务祈祷的萨拉姆之后。", "先知 ﷺ 在每次义务祈祷后都会这么说。"),
        "dua_slaughtering" to DuaText("屠宰动物时", "以真主的名义，真主是最伟大的。", "当献祭或屠宰动物时。", "先知 ﷺ 在献祭时说 Bismillah 和 takbir。"),
    )
}
